<template><view class="ppt-error"><view class="error-mark"><text>AI</text><text>×</text></view><text class="error-title">{{ title }}</text><text class="error-copy">{{ reason }}</text><text class="error-label">失败原因</text><view class="error-box"><text>{{ reason }}</text></view><text class="error-label">处理建议</text><view class="error-box"><text>{{ suggestion }}</text></view><view class="error-actions"><button @click="$emit('back')">返回修改</button><button class="primary" @click="$emit('retry')">重新生成</button></view></view></template>
<script setup lang="ts">withDefaults(defineProps<{title?:string;reason?:string;suggestion?:string}>(),{title:"PPT生成失败",reason:"服务暂时无法完成本次操作",suggestion:"检查内容和网络后重新尝试。"});defineEmits<{back:[];retry:[]}>();</script>
<style scoped>.ppt-error{padding-top:54px;text-align:center}.error-mark{position:relative;display:grid;width:100px;height:100px;margin:0 auto;place-items:center;border-radius:50%;color:#6140f7;background:#f2edff;font-size:28px;font-weight:800}.error-mark text+text{position:absolute;top:8px;right:-20px;display:grid;width:32px;height:24px;place-items:center;border-radius:12px;color:#fff;background:#f04747;font-size:12px}.error-title{display:block;margin-top:36px;font-size:18px;font-weight:800}.error-copy{display:block;margin-top:7px;color:#6b7387;font-size:11px}.error-label{display:block;margin:34px 0 9px;text-align:left;font-size:11px;font-weight:700}.error-box{padding:16px;border-radius:10px;background:#f6f7fb;color:#6b7387;text-align:left;font-size:11px}.error-actions{position:fixed;right:16px;bottom:calc(12px + env(safe-area-inset-bottom));left:16px;display:grid;grid-template-columns:150px 1fr;gap:12px}.error-actions button{height:46px;border:1px solid #e3e5f0;border-radius:11px;background:#fff;font-size:12px;font-weight:700}.error-actions .primary{border:0;color:#fff;background:#6140f7}</style>
